function Write-EllipsePgm([string]$Path){$w=640;$h=420;$phi=.45;$cos=[Math]::Cos($phi);$sin=[Math]::Sin($phi);$header=[Text.Encoding]::ASCII.GetBytes("P5`n$w $h`n255`n");$pixels=New-Object byte[] ($w*$h);for($r=0;$r -lt $h;$r++){for($c=0;$c -lt $w;$c++){$x=($c-320)*$cos+($r-210)*$sin;$y=-($c-320)*$sin+($r-210)*$cos;$inside=($x*$x/(140*140)+$y*$y/(75*75))-le 1;$pixels[$r*$w+$c]=if($inside){220}else{30}}};$bytes=New-Object byte[] ($header.Length+$pixels.Length);[Array]::Copy($header,0,$bytes,0,$header.Length);[Array]::Copy($pixels,0,$bytes,$header.Length,$pixels.Length);[IO.File]::WriteAllBytes($Path,$bytes)}
